    //     }
    //
    //   swap:
    //
    //     {
    //         "id": "105807376",
    //         "side": "buy",
    //         "px": "84410.57",
    //         "qty": "1",
    //         "amt": "84.41057",
    //         "cT": "1740777563557",
    //     }
    //
    // fetchMyTrades
    //
    //  spot:
    //
    //     {
    //         "id": "32164924331503616",
    //         "symbol": "LINK_USDT",
    //         "accountType": "SPOT",
    //         "orderId": "32164923987566592",
    //         "side": "SELL",
    //         "type": "MARKET",
    //         "matchRole": "TAKER",
    //         "createTime": 1648635115525,
    //         "price": "11",
    //         "quantity": "0.5",
    //         "amount": "5.5",
    //         "feeCurrency": "USDT",
    //         "feeAmount": "0.007975",
