    //     }
    //
    //  swap:
    //
    //     {
    //         "symbol": "BTC_USDT_PERP",
    //         "trdId": "105813553",
    //         "side": "SELL",
    //         "type": "TRADE",
    //         "mgnMode": "CROSS",
    //         "ordType": "MARKET",
    //         "clOrdId": "polo418912106147315112",
    //         "role": "TAKER",
    //         "px": "84704.9",
    //         "qty": "1",
    //         "cTime": "1740842829430",
    //         "uTime": "1740842829450",
    //         "feeCcy": "USDT",
    //         "feeAmt": "0.04235245",
    //         "deductCcy": "",
    //         "deductAmt": "0",
    //         "feeRate": "0.0005",
    //         "id": "418912106342654592",
    //         "posSide": "BOTH",
    //         "ordId": "418912106147315112",
    //         "qCcy": "USDT",
    //         "value": "84.7049",
    //         "actType": "TRADING"
    //     },
    //
    // fetchOrderTrades (taker trades)
    //
    //     {
    //         "id": "30341456333942784",
    //         "symbol": "LINK_USDT",
    //         "accountType": "SPOT",
    //         "orderId": "30249408733945856",
    //         "side": "BUY",
    //         "type": "LIMIT",
    //         "matchRole": "MAKER",
    //         "createTime": 1648200366864,
    //         "price": "3.1",
    //         "quantity": "1",
    //         "amount": "3.1",
    //         "feeCurrency": "LINK",
    //         "feeAmount": "0.00145",
    //         "pageId": "30341456333942784",
    //         "clientOrderId": ""
    //     }
    //
    market := ccxt.GetArg(optionalArgs, 0, nil)
    _ = market
    var id interface{} = this.SafeStringN(trade, []interface{}{"id", "tradeID", "trdId"})
