    //  contract:
    //
    //     {
    //         "symbol": "BTC_USDT_PERP",
    //         "side": "BUY",
    //         "type": "LIMIT",
    //         "ordId": "418890767248232148",
    //         "clOrdId": "polo418890767248232148",
    //         "mgnMode": "CROSS",
    //         "px": "81130.13",
    //         "reduceOnly": false,
    //         "lever": "20",
