    //         "execAmt": "0",
    //         "feeCcy": "",
    //         "feeAmt": "0",
    //         "deductCcy": "0",
    //         "deductAmt": "0",
    //         "stpMode": "NONE", // todo: selfTradePrevention
    //         "cTime": "1740837741523",
    //         "uTime": "1740840846882",
    //         "sz": "1",
    //         "posSide": "BOTH",
    //         "qCcy": "USDT"
    //         "cancelReason": "", // this field can only be in closed orders
    //     },
    //
    // createOrder, editOrder
    //
    //  spot:
    //
    //     {
    //         "id": "29772698821328896",
    //         "clientOrderId": "1234Abc"
    //     }
    //
    //  contract:
    //
    //    {
    //        "ordId":"418876147745775616",
