func  (this *poloniex) ParseBalance(response interface{}) interface{}  {
    var result interface{} = map[string]interface{} {
        "info": response,
        "timestamp": nil,
        "datetime": nil,
    }
    // for swap
    if !ccxt.IsTrue(ccxt.IsArray(response)) {
        var ts interface{} = this.SafeInteger(response, "uTime")
        ccxt.AddElementToObject(result, "timestamp", ts)
        ccxt.AddElementToObject(result, "datetime", this.Iso8601(ts))
        var details interface{} = this.SafeList(response, "details", []interface{}{})
        for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(details)); i++ {
            var balance interface{} = ccxt.GetValue(details, i)
            var currencyId interface{} = this.SafeString(balance, "ccy")
            var code interface{} = this.SafeCurrencyCode(currencyId)
            var account interface{} = this.Account()
            ccxt.AddElementToObject(account, "total", this.SafeString(balance, "avail"))
            ccxt.AddElementToObject(account, "used", this.SafeString(balance, "im"))
            ccxt.AddElementToObject(result, code, account)
        }
        return this.SafeBalance(result)
    }
    // for spot
    for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(response)); i++ {
        var account interface{} = this.SafeValue(response, i, map[string]interface{} {})
        var balances interface{} = this.SafeValue(account, "balances")
        for j := 0; ccxt.IsLessThan(j, ccxt.GetArrayLength(balances)); j++ {
            var balance interface{} = this.SafeValue(balances, j)
            var currencyId interface{} = this.SafeString(balance, "currency")
            var code interface{} = this.SafeCurrencyCode(currencyId)
            var newAccount interface{} = this.Account()
            ccxt.AddElementToObject(newAccount, "free", this.SafeString(balance, "available"))
            ccxt.AddElementToObject(newAccount, "used", this.SafeString(balance, "hold"))
            ccxt.AddElementToObject(result, code, newAccount)
        }
    }
    return this.SafeBalance(result)
}
